import json, re

cmds = []
entries = []
with open('.state/sessions/history/s_1774121969734_325/session.jsonl') as f:
    for line in f:
        try:
            entries.append(json.loads(line))
        except:
            pass

for i, e in enumerate(entries):
    role = e.get('role','')
    content = e.get('content','')
    if isinstance(content, list):
        for block in content:
            if isinstance(block, dict):
                text = block.get('text','')
                # Extract bash commands from tool_use blocks
                if 'bash' in str(text) and 'command' in str(text):
                    # Extract command parameter
                    m = re.search(r'"command"[:\s]*"([^"]{5,200})', str(text))
